define(['core/log'],function(Log){function safeInt(value,fallback){var parsed=parseInt(value,10);return Number.isFinite(parsed)?parsed:fallback;}function pad(value){value=Math.max(0,Math.floor(value));return value<10?'0'+value:''+value;}function formatSeconds(seconds){seconds=Math.max(0,Math.round(Number(seconds)||0));var hours=Math.floor(seconds/3600);var minutes=Math.floor((seconds%3600)/60);var secs=seconds%60;if(hours>0){return hours+':'+pad(minutes)+':'+pad(secs);}return pad(minutes)+':'+pad(secs);}function fetchTextWithTimeout(url){var timeout=10000;if(window.AbortController){var controller=new AbortController();var timer=window.setTimeout(function(){controller.abort();},timeout);return fetch(url,{signal:controller.signal,credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(response){return response.ok?response.text():Promise.reject(response.status);}).finally(function(){window.clearTimeout(timer);});}return Promise.race([fetch(url,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(response){return response.ok?response.text():Promise.reject(response.status);}),new Promise(function(resolve,reject){window.setTimeout(function(){reject('timeout');},timeout);})]);}function sessionSet(key,value,context){try{window.sessionStorage.setItem(key,value);}catch(error){Log.debug('mod_videotrack: could not save '+(context||'session state')+' - '+error);}return Promise.resolve();}function sessionGet(key,context){var value=null;try{value=window.sessionStorage.getItem(key);}catch(error){Log.debug('mod_videotrack: could not read '+(context||'session state')+' - '+error);}return value;}return{safeInt:safeInt,formatSeconds:formatSeconds,fetchTextWithTimeout:fetchTextWithTimeout,sessionSet:sessionSet,sessionGet:sessionGet};});
